import React from "react";
import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import AttendanceList from "./pages/attendance/AttendanceList";
import AttendanceAnalytics from "./pages/attendance/AttendanceAnalytics";
import ReportsAttendance from "./pages/reports/ReportsAttendance";
import WorkAnniversaryAlert from "./pages/alerts/WorkAnniversaryAlert";
import ExcessiveLeaveAlert from "./pages/alerts/ExcessiveLeaveAlert";
import "./App.scss";

function App() {
  return (
    <Router>
      <div style={{ display: "flex", minHeight: "100vh" }}>
        {/* Sidebar đơn giản để test */}
        <div style={{ width: "250px", background: "#1f2937", color: "white", padding: "2rem" }}>
          <h2 style={{ fontSize: "1.5rem", marginBottom: "2rem" }}>HR System</h2>
          <nav style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
            <Link to="/" style={{ color: "white", textDecoration: "none" }}>Chấm công hôm nay</Link>
            <Link to="/analytics" style={{ color: "white", textDecoration: "none" }}>Phân tích</Link>
            <Link to="/reports" style={{ color: "white", textDecoration: "none" }}>Báo cáo tổng hợp</Link>
            <Link to="/alerts/anniversary" style={{ color: "white", textDecoration: "none" }}>Kỷ niệm làm việc</Link>
            <Link to="/alerts/leave" style={{ color: "white", textDecoration: "none" }}>Cảnh báo nghỉ phép</Link>
          </nav>
        </div>

        {/* Nội dung chính */}
        <div style={{ flex: 1, backgroundColor: "#f3f4f6" }}>
          <Routes>
            <Route path="/" element={<AttendanceList />} />
            <Route path="/analytics" element={<AttendanceAnalytics />} />
            <Route path="/reports" element={<ReportsAttendance />} />
            <Route path="/alerts/anniversary" element={<WorkAnniversaryAlert />} />
            <Route path="/alerts/leave" element={<ExcessiveLeaveAlert />} />
          </Routes>
        </div>
      </div>
    </Router>
  );
}

export default App;
